const site=()=>state.data?.site||{};
const socialIcon=(name)=>({instagram:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="2.5" y="2.5" width="19" height="19" rx="5"/><circle cx="12" cy="12" r="4.2"/><circle cx="17.7" cy="6.5" r="1" fill="currentColor" stroke="none"/></svg>',facebook:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M13.7 21v-8.2h2.8l.5-3.3h-3.3V7.4c0-.95.35-1.6 1.7-1.6H17V2.9c-.3-.05-1.4-.15-2.65-.15-2.65 0-4.45 1.6-4.45 4.55v2.2H7v3.3h2.9V21h3.8z"/></svg>',tiktok:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M16.6 2.5c.2 2 1.3 3.2 3.3 3.35v3.55a8.5 8.5 0 0 1-3.2-.75v6.15c0 4.1-2.65 6.65-6.25 6.65-3.35 0-5.9-2.5-5.9-5.75 0-3.7 2.8-6.15 6.85-6.15v3.55c-2.1-.2-3.4 1-3.4 2.6 0 1.4 1.15 2.35 2.5 2.35 1.5 0 2.5-1.05 2.5-2.8V2.5h3.6z"/></svg>'}[name]||'');
const socialLinks=(compact=false)=>[['instagram','Instagram'],['facebook','Facebook'],['tiktok','TikTok']].filter(([k])=>site()[k]).map(([k,label])=>`<a class="social-link" href="${esc(site()[k])}" target="_blank" rel="noopener noreferrer" aria-label="${label}" title="${label}">${socialIcon(k)}${compact?'':`<span>${label}</span>`}</a>`).join('');

const nav=(active='')=>`<header class="nav nav-premium"><a class="brand" href="/" aria-label="Ristorante Oasi, homepage"><span class="brand-mark">L’OASI<span class="brand-dot">.</span></span><span class="brand-sub">HOTEL · RISTORANTE · RICEVIMENTI</span></a><button class="hamburger" id="hamburger" aria-label="Apri menu" aria-expanded="false"><svg class="oasi-menu-icon" viewBox="0 0 28 28" width="29" height="29" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4 9h20M4 19h20"/></svg></button><nav id="links" aria-label="Navigazione principale"><a href="/chi-siamo">Chi siamo</a><a href="/menu">Menù</a><a href="/galleria">Galleria</a><a href="/eventi-cerimonie">Eventi</a><a href="/#contatti">Contatti</a><div class="nav-social">${socialLinks(true)}</div><a class="nav-book" href="/prenota">Prenota un tavolo <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></nav></header>`;
const footer=()=>`<footer class="footer footer-premium"><div class="footer-feature"><div class="eyebrow">UN INVITO A STARE BENE</div><h2>Ci vediamo <em>all’Oasi.</em></h2><a class="footer-cta" href="/prenota"><span class="footer-cta-label">Prenota la tua esperienza</span><span class="footer-cta-arrow" aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div><div class="footer-content"><div class="footer-brand"><strong>L’OASI</strong><span>F.LLI FERA · DAL 1997</span><p>Il gusto dell’ospitalità, da generazioni.</p><div class="footer-social">${socialLinks(true)}</div></div><div><h4>ESPLORA</h4><a href="/chi-siamo">Chi siamo</a><a href="/menu">Menù</a><a href="/galleria">Galleria</a><a href="/eventi-cerimonie">Eventi e cerimonie</a><a href="/prenota">Prenota</a></div><div><h4>VIENI A TROVARCI</h4><p>${esc(site().address||'Contrada Serrarossa, 88835 Roccabernarda KR')}</p><a href="tel:+393387036868">${esc(site().phone||'338 703 6868')}</a><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=Contrada+Serrarossa+Roccabernarda">Apri indicazioni <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Ristorante Oasi · F.lli Fera</span><span><a href="/privacy">Privacy</a><a href="/admin">Area riservata</a></span></div></footer>`;
const placeholder='https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=1400&q=85';
const home=()=>{const d=site(),photos=state.data.gallery||[],fallback=[{image_url:'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=900&q=85',caption:'Ambienti',category:'Ambienti'},{image_url:'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=900&q=85',caption:'La cucina',category:'Cucina'},{image_url:'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=900&q=85',caption:'Eventi',category:'Eventi'}];return `${nav()}<main class="premium-site"><section class="hero hero-premium" style="--hero:url('${esc(d.heroImage||placeholder)}')"><div class="hero-inner"><div class="kicker light">RISTORANTE OASI <span class="kicker-line"></span> DAL 1997</div><h1>Ogni incontro<br>diventa <i>speciale.</i></h1><p>${esc(d.subtitle||'Accoglienza autentica, cucina e momenti da ricordare.')}</p><div class="hero-actions"><a class="btn btn-light" href="/prenota">Prenota un tavolo <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a><a class="hero-ghost" href="/menu">Scopri il menù <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div></div><div class="hero-bottom"><span>ROCCABERNARDA · CROTONE</span><span>SCOPRI L'OASI ↓</span></div></section><div class="premium-highlights"><div class="highlight-item"><div><strong>Dal 1997</strong><small>Una storia di ospitalità</small></div></div><div class="highlight-item"><div><strong>La nostra cucina</strong><small>Il valore di ogni ingrediente</small></div></div><div class="highlight-item"><div><strong>Momenti da vivere</strong><small>Il piacere di stare insieme</small></div></div></div><section class="intro section premium-intro" id="chi-siamo"><div class="split"><div class="intro-media"><img src="${esc(d.storyImage||'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1000&q=85')}" alt="Atmosfera del Ristorante Oasi" loading="lazy"/><div class="image-stamp">DAL <strong>1997</strong><small>F.LLI FERA</small></div></div><div class="intro-copy"><div class="eyebrow">LA NOSTRA ESSENZA</div><h2>Il piacere<br>di sentirsi <em>accolti.</em></h2><div class="gold-rule"></div><p>${esc(d.story||'Un luogo da vivere, tra cucina, convivialità e cura per ogni dettaglio.')}</p><a href="/prenota" class="premium-text-link">Vieni a trovarci <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div></div></section><section class="oasi-events section" id="eventi"><div class="oasi-events-image"><img src="https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=1400&q=85" loading="lazy" alt="Tavola elegante allestita per ricevimento"/></div><div class="oasi-events-copy"><div class="eyebrow">RICEVIMENTI · EMOZIONI · RICORDI</div><h2>I giorni che<br><em>porti nel cuore.</em></h2><p>Una festa attesa a lungo, le persone più care, la gioia di ritrovarsi. All’Oasi ogni occasione è fatta di piccoli dettagli e grandi emozioni.</p><a class="btn btn-dark" href="/eventi-cerimonie">Scopri il mondo dei ricevimenti <span aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div></section><section class="section oasi-actions" aria-labelledby="oasi-actions-title"><div class="section-head"><div><div class="eyebrow">VIVI L’OASI</div><h2 id="oasi-actions-title">Scegli il tuo <em>momento.</em></h2></div><p>Tre modi per vivere l'Oasi, dalla tavola alle occasioni più importanti.</p></div><div class="oasi-action-grid"><a class="oasi-action-card" href="/menu"><img src="https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1100&q=85" alt="Un piatto della cucina" loading="lazy"/><span class="oasi-action-shade"></span><span class="oasi-action-content"><small>LA NOSTRA PROPOSTA</small><strong>Esplora il menù</strong><span>Scopri piatti, pizze e carta dei vini.</span></span><span class="oasi-action-icon" aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a><a class="oasi-action-card" href="/prenota"><img src="https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=1100&q=85" alt="Tavoli pronti per il servizio" loading="lazy"/><span class="oasi-action-shade"></span><span class="oasi-action-content"><small>UN POSTO PER TE</small><strong>Prenota un tavolo</strong><span>Scegli il giorno e l'orario che preferisci.</span></span><span class="oasi-action-icon" aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a><a class="oasi-action-card" href="/eventi-cerimonie#richiedi-evento"><img src="https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=1100&q=85" alt="Tavola allestita per una cerimonia" loading="lazy"/><span class="oasi-action-shade"></span><span class="oasi-action-content"><small>LE OCCASIONI SPECIALI</small><strong>Organizza un evento</strong><span>Raccontaci la tua idea e richiedi informazioni.</span></span><span class="oasi-action-icon" aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div><div class="oasi-actions-gallery-link"><a class="premium-text-link" href="/galleria">Scopri le fotografie del ristorante <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></div></section><section class="contact section premium-contact" id="contatti"><div><div class="eyebrow">CI VEDIAMO ALL’OASI</div><h2>Il tuo prossimo<br><em>bel momento.</em></h2><p>${esc(d.address||'Contrada Serrarossa, 88835 Roccabernarda KR')}</p><p>Martedì – domenica · Pranzo e cena</p><div class="footer-social contact-social">${socialLinks(true)}</div></div><div class="contact-premium-card"><span>PRENOTAZIONI & INFORMAZIONI</span><h3>Ti aspettiamo.</h3><p>Riserva il tuo tavolo oppure chiamaci per un’occasione speciale.</p><a href="/prenota" class="btn btn-dark">Prenota ora <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></a><a class="contact-call" href="tel:+393387036868">${esc(d.phone||'338 703 6868')} <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></a><a class="contact-map" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=Contrada+Serrarossa+Roccabernarda">Come raggiungerci <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></a><div class="oasi-map-wrap"><iframe title="Mappa Ristorante Oasi a Roccabernarda" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://maps.google.com/maps?q=Contrada%20Serrarossa%2C%2088835%20Roccabernarda%20KR&t=&z=14&ie=UTF8&iwloc=&output=embed"></iframe><a class="oasi-map-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=Contrada+Serrarossa%2C+88835+Roccabernarda+KR">Apri il percorso <span aria-hidden="true">↗</span></a></div></div></section></main>${footer()}`};
const aboutPage=()=>{const d=site();return `${nav('chi-siamo')}<main class="story-page"><section class="dedicated-hero"><div class="eyebrow">RISTORANTE OASI · DAL 1997</div><h1>La nostra <em>storia.</em></h1><p>Un luogo dove ospitalità, cucina e tradizione si incontrano.</p></section><section class="dedicated-story"><div class="dedicated-story-visual"><img src="${esc(d.storyImage||'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1400&q=85')}" alt="Gli ambienti del Ristorante Oasi" loading="lazy"/><span class="dedicated-stamp">DAL 1997 · F.LLI FERA</span></div><article class="dedicated-story-copy"><div class="eyebrow">CHI SIAMO</div><h2>Il piacere di sentirsi <em>a casa.</em></h2><div class="gold-rule"></div><p class="story-user-text">${esc(d.story||'La nostra storia nasce dalla passione per la cucina e per l’ospitalità. Presto racconteremo qui ogni dettaglio della nostra esperienza.')}</p><a class="btn btn-dark" href="/prenota">Prenota la tua visita <span aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></article></section><section class="dedicated-outro"><div class="eyebrow">UN INVITO A STARE INSIEME</div><h2>Ogni incontro è una <em>storia da ricordare.</em></h2><a href="/galleria" class="premium-text-link">Scopri gli ambienti <span aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a></section></main>${footer()}`};
const galleryPage=()=>{const photos=state.data?.gallery||[];const fallback=[{image_url:'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=1100&q=85',caption:'Gli ambienti',category:'Ambienti'},{image_url:'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1100&q=85',caption:'L’atmosfera',category:'Ambienti'},{image_url:'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=1100&q=85',caption:'I dettagli',category:'Ambienti'}];const items=photos;const cats=['Tutte',...new Set(items.map(p=>p.category||'Ambienti'))];return `${nav('galleria')}<main class="gallery-page"><section class="dedicated-hero"><div class="eyebrow">ATMOSFERE · SAPORI · EMOZIONI</div><h1>La nostra <em>galleria.</em></h1><p>Le immagini raccontano i momenti, le persone e i dettagli che ci rendono speciali.</p></section><section class="dedicated-gallery"><div class="gallery-filter-row" aria-label="Filtra la galleria">${cats.map((c,i)=>`<button class="gallery-filter ${i===0?'chosen':''}" type="button" data-gallery-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="dedicated-gallery-grid">${items.map((p,i)=>`<button type="button" class="dedicated-gallery-item" data-gallery-index="${i}" data-gallery-category="${esc(p.category||'Ambienti')}" aria-label="Apri fotografia: ${esc(p.caption||'Ristorante Oasi')}"><img src="${esc(p.image_url)}" loading="lazy" alt="${esc(p.caption||'Ristorante Oasi')}"/><span>${esc(p.caption||'Ristorante Oasi')}</span><span class="gallery-zoom" aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></button>`).join('')}</div></section><div id="gallery-lightbox" class="gallery-lightbox" hidden role="dialog" aria-modal="true" aria-label="Fotografia ingrandita"><button class="lightbox-close" type="button" aria-label="Chiudi fotografia">×</button><img alt=""/><p></p></div></main>${footer()}`};
const book=()=>`${nav()}<main class="page"><div class="page-top"><div class="eyebrow">OASI / PRENOTAZIONI</div><h1>Riserva il tuo <em>tavolo.</em></h1><p>Seleziona giorno e orario: penseremo noi ad assegnarti il tavolo più adatto.</p></div><div class="booking-layout"><form id="booking" class="panel"><h3>La tua prenotazione</h3><div class="fields two"><label>Data<input type="date" name="date" required min="${new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Rome'})}"/></label><label>Servizio<select name="service"><option value="lunch">Pranzo</option><option value="dinner">Cena</option></select></label><label>Orario di arrivo<input type="time" name="time" value="12:30" required /></label><label>Persone<select name="party_size">${Array.from({length:9},(_,i)=>`<option value="${i+1}" ${i===1?'selected':''}>${i+1} ${i?'persone':'persona'}</option>`).join('')}</select></label></div><button type="button" id="check-availability" class="btn btn-outline full">Verifica disponibilità <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></button><div id="availability" class="availability-note">Verifica la disponibilità prima di inserire i tuoi dati.</div><div class="fields two"><label>Nome e cognome<input name="name" maxlength="120" required placeholder="Nome e cognome"/></label><label>Telefono<input type="tel" name="phone" maxlength="40" required placeholder="Numero di telefono"/></label><label>Email<input type="email" name="email" required placeholder="nome@email.it"/></label><label>Note (facoltative)<input name="notes" maxlength="600" placeholder="Allergie, esigenze..."/></label></div><label class="check-line"><input type="checkbox" required/> Ho letto l'<a href="/privacy" target="_blank">informativa privacy</a> e acconsento al trattamento dei dati necessari alla prenotazione.</label><button class="btn btn-dark full" type="submit">Conferma prenotazione <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></button><p class="tiny">Per gruppi di 10 o più persone chiamaci al <a href="tel:+393387036868">338 703 6868</a>.</p></form><aside class="booking-side"><img src="https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=900&q=85" alt="Tavola apparecchiata"/><div><div class="eyebrow">TI ASPETTIAMO</div><h3>Un momento speciale, a ogni tavolo.</h3><p>Una prenotazione è confermata solo quando il sistema mostra il numero di conferma.</p></div></aside></div></main>${footer()}`;
const menupage=()=>{const items=state.data.menu||[],sections=[['Piatti','piatti'],['Pizze','pizze'],['Vini','vini']];return `${nav()}<main class="page"><div class="page-top"><div class="eyebrow">LA NOSTRA PROPOSTA</div><h1>Il nostro <em>menù.</em></h1><p>Scegli tra i sapori della nostra cucina, le pizze e la carta dei vini.</p></div><div class="menu-filter">${sections.map(([l,v])=>`<button data-filter="${v}">${l}</button>`).join('')}</div><div class="menu-container">${sections.map(([label,section])=>`<section class="menu-section" data-section="${section}"><h2>${label}</h2>${items.filter(x=>x.section===section).length?Object.entries(Object.groupBy(items.filter(x=>x.section===section),x=>x.category||label)).map(([cat,list])=>`<h3>${esc(cat)}</h3><div class="menu-list">${list.map(x=>`<article class="menu-item">${x.image_url?`<img src="${esc(x.image_url)}" alt="${esc(x.name)}"/>`:''}<div><h4>${esc(x.name)}</h4><p>${esc(x.description)}</p>${x.allergens?`<small>Allergeni: ${esc(x.allergens)}</small>`:''}${x.region?`<small>${esc(x.region)} ${esc(x.winery)} ${esc(x.vintage)}</small>`:''}</div><strong>${esc(x.price)}</strong></article>`).join('')}</div>`).join(''):'<p>Stiamo aggiornando questa sezione del menù.</p>'}</section>`).join('')}</div></main>${footer()}`};
const privacy=()=>`${nav()}<main class="page"><div class="page-top"><h1>Informativa <em>privacy.</em></h1><p>Questa pagina è un modello provvisorio da completare e verificare con il titolare prima della pubblicazione.</p></div><section class="section"><h2>Gestione delle prenotazioni</h2><p>I dati forniti nella prenotazione (nome, recapiti, numero di persone, note e data) sono utilizzati per gestire la richiesta e comunicare con il cliente. Il titolare del trattamento deve inserire qui denominazione legale, recapiti privacy, basi giuridiche, tempi di conservazione, fornitori e diritti degli interessati in una informativa GDPR completa.</p></section></main>${footer()}`;
const cancel=()=>`${nav()}<main class="page"><div class="page-top"><div class="eyebrow">GESTIONE PRENOTAZIONE</div><h1>Annulla la <em>prenotazione.</em></h1><p>Questa azione libera il tavolo assegnato. Non può essere annullata.</p><button id="cancel-booking" class="btn btn-dark">Conferma annullamento</button><p id="cancel-response"></p></div></main>${footer()}`;
const inputData=f=>Object.fromEntries(new FormData(f));
const bindPublic=()=>{const evtForm=$('#event-request');if(evtForm)evtForm.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(evtForm);const message=`Buongiorno, vorrei informazioni per organizzare un evento all'Oasi.\nTipologia: ${d.get('type')}\nData indicativa: ${d.get('date')}\nInvitati: ${d.get('guests')}\nNote: ${d.get('note')||'Nessuna'}`;window.open('https://wa.me/393387036868?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});if(location.pathname==='/galleria'){const modal=$('#gallery-lightbox'),photo=modal?.querySelector('img'),caption=modal?.querySelector('p');const close=()=>{modal.hidden=true;document.body.classList.remove('lightbox-open')};document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-gallery-filter]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');document.querySelectorAll('[data-gallery-index]').forEach(x=>x.hidden=b.dataset.galleryFilter!=='Tutte'&&x.dataset.galleryCategory!==b.dataset.galleryFilter)}));document.querySelectorAll('[data-gallery-index]').forEach(b=>b.addEventListener('click',()=>{photo.src=b.querySelector('img').src;photo.alt=b.querySelector('img').alt;caption.textContent=photo.alt;modal.hidden=false;document.body.classList.add('lightbox-open')}));{const cat=new URLSearchParams(location.search).get('categoria');if(cat&&cat!=='Tutte'){const b=[...document.querySelectorAll('[data-gallery-filter]')].find(x=>x.dataset.galleryFilter.toLowerCase()===cat.toLowerCase());b?.click()}}modal?.querySelector('.lightbox-close')?.addEventListener('click',close);modal?.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal?.hidden)close()})}document.querySelectorAll('a[href^="/#"], a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const url=new URL(link.href,location.href);if(url.pathname!=='/'||!url.hash)return;if(location.pathname==='/' ){const destination=document.getElementById(decodeURIComponent(url.hash.slice(1)));if(destination){event.preventDefault();history.pushState(null,'',url.pathname+url.hash);document.getElementById('links')?.classList.remove('open');destination.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}}));$('#hamburger')?.addEventListener('click',()=>{const opened=$('#links').classList.toggle('open');$('#hamburger').setAttribute('aria-expanded',String(opened));$('#hamburger').setAttribute('aria-label',opened?'Chiudi menu':'Apri menu')});if($('#booking')){const f=$('#booking');const bcfg=state.data.booking||{};const setTime=()=>{const service=f.elements.service.value;f.elements.time.value=bcfg[service]?.start||'12:30';f.elements.time.min=bcfg[service]?.start||'00:00';f.elements.time.max=bcfg[service]?.last||'23:59'};f.elements.service.addEventListener('change',setTime);setTime();$('#check-availability').onclick=async()=>{const b=inputData(f);try{const q=new URLSearchParams({date:b.date,service:b.service,time:b.time,party_size:b.party_size});const o=await api('availability?'+q);$('#availability').textContent=o.available?'✓ Disponibile · '+o.rooms.map(x=>x.name).join(', '):'Nessun tavolo disponibile in questo momento';$('#availability').className='availability-note '+(o.available?'success':'error')}catch(e){$('#availability').textContent=e.message;$('#availability').className='availability-note error'}};f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('[type=submit]');btn.disabled=true;try{const o=await api('book','POST',inputData(f));f.innerHTML=`<div class="success-card"><div class="eyebrow">PRENOTAZIONE CONFERMATA</div><h2>Ti aspettiamo!</h2><p>La tua prenotazione n° <strong>${o.id}</strong> è confermata per il ${esc(o.date)} alle ${esc(o.time)}, per ${o.party_size} persone.</p><p>${o.email_sent_configured?'Riceverai una email di conferma.':'L’invio email non è ancora attivato: conserva il collegamento qui sotto per annullare.'}</p><a class="text-link" href="${esc(o.cancel_url)}">Gestisci o annulla prenotazione <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></a></div>`}catch(e){msg(e.message,'error')}finally{btn.disabled=false}}}if($('#cancel-booking'))$('#cancel-booking').onclick=async()=>{try{await api('cancel','POST',{token:new URLSearchParams(location.search).get('token')});$('#cancel-response').textContent='Prenotazione annullata correttamente.';$('#cancel-booking').disabled=true}catch(e){msg(e.message,'error')}};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');document.querySelectorAll('.menu-section').forEach(x=>x.hidden=x.dataset.section!==b.dataset.filter)});};
const eventsPage=()=>{const pics=(state.data?.gallery||[]).filter(x=>/event|cerimoni|matrimon|riceviment/i.test(x.category||''));return `${nav('eventi')}<main class="oasi-event-page"><section class="event-hero event-hero-premium"><div class="event-hero-photo"><img src="https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=1900&q=85" alt="Ricevimento elegante al Ristorante Oasi"/></div><div class="event-hero-overlay"></div><div class="event-hero-text"><span class="eyebrow">RICEVIMENTI · CERIMONIE · EVENTI</span><h1>Il luogo in cui<br><em>i ricordi prendono vita.</em></h1><p>All’Oasi ogni evento nasce da un’atmosfera da vivere insieme: matrimoni, cerimonie, feste private e occasioni da ricordare con le persone più importanti.</p><div class="event-hero-actions"><a class="btn btn-light" href="#richiedi-evento">Richiedi informazioni <span><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></a><a class="event-hero-link" href="tel:+393387036868">Oppure chiamaci al ${esc(site().phone||'338 703 6868')}</a></div></div><div class="event-hero-facts"><div><strong>Matrimoni</strong><span>Atmosfera, accoglienza e cura del dettaglio.</span></div><div><strong>Cerimonie</strong><span>Battesimi, comunioni, anniversari e momenti di famiglia.</span></div><div><strong>Eventi privati</strong><span>Compleanni, feste e occasioni speciali da condividere.</span></div></div></section><section class="section event-story"><div class="event-story-copy"><div class="eyebrow">UN’OSPITALITÀ CHE SI RICORDA</div><h2>Ogni occasione merita<br><em>un’atmosfera speciale.</em></h2><p>Ci sono giornate che si aspettano a lungo e momenti che riuniscono le persone più care. Per questo la pagina Eventi dell’Oasi non deve solo informare: deve far sentire il valore del tempo condiviso, la cura dell’accoglienza e il piacere di festeggiare in un luogo elegante.</p><p>Dalla tavola allestita con attenzione agli spazi dedicati ai ricevimenti, accompagniamo ogni occasione con uno stile sobrio, raffinato e autentico.</p></div><div class="event-story-media"><img src="https://images.unsplash.com/photo-1519225421980-715cb0215aed?w=1200&q=85" alt="Allestimento floreale per cerimonia" loading="lazy"/><div class="event-story-badge"><span>DAL 1997</span><strong>Ospitalità & ricevimenti</strong></div></div></section><section class="section event-offers"><div class="section-head"><div><div class="eyebrow">COSA POSSIAMO OSPITARE</div><h2>I vostri momenti, <em>con il tono giusto.</em></h2></div><p>Dalle ricorrenze di famiglia agli eventi più attesi, ogni occasione può trovare il suo spazio all’Oasi.</p></div><div class="event-offer-grid"><article class="event-offer-card"><img src="https://images.unsplash.com/photo-1511285560929-80b456fea0bc?w=1200&q=85" alt="Matrimonio elegante" loading="lazy"/><div><small>MATRIMONI</small><h3>Il giorno più atteso.</h3><p>Un contesto accogliente e curato, da vivere con le persone che contano davvero.</p><ul><li>Atmosfera elegante</li><li>Spazi dedicati al ricevimento</li><li>Richiesta informazioni personalizzata</li></ul></div></article><article class="event-offer-card"><img src="https://images.unsplash.com/photo-1464207687429-7505649dae38?w=1200&q=85" alt="Cerimonia con tavoli preparati" loading="lazy"/><div><small>CERIMONIE</small><h3>Le tappe della vita.</h3><p>Battesimi, comunioni, cresime e anniversari da condividere in un luogo che sappia accogliere.</p><ul><li>Pranzi e cene di famiglia</li><li>Organizzazione semplice e chiara</li><li>Contatto diretto con il personale</li></ul></div></article><article class="event-offer-card"><img src="https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?w=1200&q=85" alt="Evento privato e festa" loading="lazy"/><div><small>EVENTI PRIVATI</small><h3>Ogni festa ha il suo stile.</h3><p>Compleanni, eventi aziendali e occasioni speciali da raccontare insieme, nel modo più adatto.</p><ul><li>Feste private</li><li>Ricorrenze e ricordi</li><li>Richiesta rapida via WhatsApp</li></ul></div></article></div></section><section class="section event-reasons"><div class="section-head"><div><div class="eyebrow">PERCHÉ OASI</div><h2>Un modo di ricevere<br><em>fatto di dettagli.</em></h2></div><p>Non solo uno spazio, ma un’esperienza costruita intorno alle persone, all’atmosfera e al piacere di stare bene insieme.</p></div><div class="event-reasons-grid"><article><strong>Ambienti curati</strong><p>Sale e spazi pensati per accogliere con stile e armonia.</p></article><article><strong>Accoglienza autentica</strong><p>Un’impostazione familiare, elegante e mai impersonale.</p></article><article><strong>Contatto diretto</strong><p>Puoi inviare una richiesta rapida e parlare subito con il personale.</p></article></div></section>${pics.length?`<section class="event-real-gallery section"><div class="section-head"><div><div class="eyebrow">SCATTI DAI NOSTRI EVENTI</div><h2>I ricordi <em>prendono forma.</em></h2></div><p>Quando caricherai foto reali da ADMIN, questa sezione diventerà ancora più autentica.</p></div><div class="oasi-event-photos">${pics.slice(0,6).map(p=>`<img src="${esc(p.image_url)}" alt="${esc(p.caption||'Ricevimenti Oasi')}" loading="lazy"/>`).join('')}</div></section>`:''}<section class="section oasi-event-enquiry" id="richiedi-evento"><div class="event-enquiry-copy"><div class="eyebrow">RICHIEDI INFORMAZIONI</div><h2>Parliamo del vostro<br><em>prossimo evento.</em></h2><p>Compila i dati principali e prepareremo un messaggio WhatsApp già pronto, così potrai inviarlo direttamente al nostro staff e ricevere una risposta nel modo più semplice.</p><div class="event-contact-box"><div><span>Telefono</span><a href="tel:+393387036868">${esc(site().phone||'338 703 6868')}</a></div><div><span>Dove siamo</span><p>${esc(site().address||'Contrada Serrarossa, 88835 Roccabernarda KR')}</p></div></div></div><form id="event-request" class="oasi-enquiry-form event-enquiry-form"><label>Che evento stai organizzando?<select name="type" required><option>Matrimonio</option><option>Battesimo</option><option>Comunione / Cresima</option><option>Compleanno</option><option>Anniversario</option><option>Evento aziendale</option><option>Altro</option></select></label><label>Data indicativa<input name="date" type="date" required/></label><label>Numero invitati<input name="guests" type="number" min="1" max="1000" required/></label><label>Nome e cognome<input name="name" type="text" placeholder="Come possiamo chiamarti?" required/></label><label>Telefono<input name="phone" type="tel" placeholder="Numero di contatto" required/></label><label>Raccontaci qualcosa in più<textarea name="note" rows="4" placeholder="Tipologia di evento, desideri particolari, orario, esigenze specifiche…"></textarea></label><button class="btn btn-dark" type="submit">Prepara richiesta WhatsApp <span aria-hidden="true"><svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></span></button><p class="small-note">Nessun invio automatico: si aprirà WhatsApp con il messaggio già compilato e sarai tu a decidere se inviarlo.</p></form></section></main>${footer()}`};
function renderPublic(){const path=location.pathname;root.innerHTML=path==='/prenota'?book():path==='/menu'?menupage():path==='/chi-siamo'?aboutPage():path==='/galleria'?galleryPage():path==='/eventi-cerimonie'?eventsPage():path==='/privacy'?privacy():path==='/annulla'?cancel():home();bindPublic();if(location.hash&&location.pathname==='/'){requestAnimationFrame(()=>{const destination=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(destination)destination.scrollIntoView({behavior:'instant',block:'start'});});}}

const adminShell=(content,tab='dashboard')=>`<div class="admin"><aside class="sidebar"><a href="/" class="side-brand"><img src="/logo-oasi.png" alt="Oasi"/></a><p class="tiny">PANNELLO AMMINISTRATORE</p>${[['dashboard','Panoramica'],['reservations','Prenotazioni'],['floor','Piantina tavoli'],['rooms','Sale e ambienti'],['menu','Menù digitale'],['gallery','Galleria'],['site','Contenuti e contatti'],['booking','Orari e regole']].map(([k,v])=>`<button class="side-item ${tab===k?'active':''}" data-tab="${k}">${v}</button>`).join('')}<button id="logout" class="side-item">Esci <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></button><a href="/" class="side-link">← Torna al sito</a></aside><div class="admin-main"><div class="admin-mobile"><img src="/logo-oasi.png" alt="Oasi"/><select id="mobile-tab">${[['dashboard','Panoramica'],['reservations','Prenotazioni'],['floor','Piantina tavoli'],['rooms','Sale e ambienti'],['menu','Menù digitale'],['gallery','Galleria'],['site','Contenuti e contatti'],['booking','Orari e regole']].map(([k,v])=>`<option value="${k}" ${tab===k?'selected':''}>${v}</option>`).join('')}</select></div>${content}</div></div>`;
const heading=(h,sub)=>`<div class="admin-head"><div><div class="eyebrow">RISTORANTE OASI / ADMIN</div><h1>${h}</h1><p>${sub||''}</p></div></div>`;
const fields=(arr,d={})=>arr.map(([key,label,type='text'])=>`<label>${label}${type==='textarea'?`<textarea name="${key}" rows="4">${esc(d[key])}</textarea>`:type==='checkbox'?`<input type="checkbox" name="${key}" ${d[key]?'checked':''}/>`:`<input name="${key}" type="${type}" value="${esc(d[key]??'')}" />`}</label>`).join('');
const sectionForm=(title,inputs,submit='Salva')=>`<section class="panel"><h3>${title}</h3><form id="editor-form"><div class="fields two">${inputs}</div><div class="form-actions"><button class="btn btn-dark" type="submit">${submit} <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></button><button class="btn btn-outline" type="button" id="form-cancel">Annulla</button></div></form></section>`;
const parseForm=f=>{const o=inputData(f);f.querySelectorAll('[type=checkbox]').forEach(x=>o[x.name]=x.checked?1:0);return o};
async function loadAdmin(){try{await api('admin/me');state.user=true}catch{state.user=false}if(!state.user){root.innerHTML=`<main class="login-wrap"><div class="login-card"><img src="/logo-oasi.png" alt="Oasi"/><div class="eyebrow">AREA RISERVATA</div><h1>Benvenuto.</h1><p>Inserisci le credenziali per accedere al gestionale.</p><form id="login"><label>Email<input type="email" name="email" required/></label><label>Password<input type="password" name="password" required/></label><button class="btn btn-dark full">Accedi <svg class="oasi-arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg></button></form><p class="tiny"><a href="/">← Torna al sito</a></p></div></main>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('admin/login','POST',inputData(e.target));state.user=true;renderAdmin()}catch(x){msg(x.message,'error')}};return}renderAdmin()}
async function renderAdmin(){const tab=state.adminView;let html='';try{
if(tab==='dashboard'){const v=await api('admin/dashboard?date='+state.date);const guests=v.bookings.reduce((s,x)=>s+x.guests,0),total=v.bookings.reduce((s,x)=>s+x.bookings,0);html=heading('Panoramica','Prenotazioni e andamento del ristorante.')+`<label>Seleziona giorno <input id="admin-date" type="date" value="${state.date}"/></label><div class="stats"><div class="stat"><span>Prenotazioni oggi</span><b>${total}</b></div><div class="stat"><span>Coperti previsti</span><b>${guests}</b></div><div class="stat"><span>Servizi attivi</span><b>${v.bookings.length}</b></div></div><section class="panel"><h3>Andamento mensile</h3><div class="table-scroll"><table><tr><th>Mese</th><th>Prenotazioni</th><th>Coperti</th></tr>${v.months.map(x=>`<tr><td>${esc(x.month)}</td><td>${x.bookings}</td><td>${x.guests}</td></tr>`).join('')}</table></div></section>`}
if(tab==='reservations'){const arr=await api('admin/reservations?date='+state.date);state.reservations=arr;html=heading('Prenotazioni','Inserisci anche quelle ricevute telefonicamente.')+`<div class="toolbar"><label>Data <input id="admin-date" type="date" value="${state.date}"/></label><button class="btn btn-dark" id="new-book">+ Nuova prenotazione</button></div><div id="edit-area"></div><section class="panel"><div class="table-scroll"><table><tr><th>Ora</th><th>Cliente</th><th>Persone</th><th>Sala / tavolo</th><th>Telefono</th><th>Stato</th><th>Azioni</th></tr>${arr.map(r=>`<tr><td>${esc(r.time)}</td><td><strong>${esc(r.name)}</strong><br/><small>${esc(r.notes)}</small></td><td>${r.party_size}</td><td>${esc(r.table_codes||'—')}</td><td>${esc(r.phone)}</td><td>${esc(r.status)}</td><td>${r.status==='confirmed'?`<button class="mini" data-move="${r.id}">Sposta</button> <button class="mini danger" data-cancel="${r.id}">Annulla</button>`:''}</td></tr>`).join('')}</table></div></section>`}
if(tab==='rooms'){state.rooms=await api('admin/rooms');html=heading('Sale e ambienti','Attiva il giardino online quando desideri aprirlo alle prenotazioni.')+`<div id="edit-area"></div><button class="btn btn-dark" id="new-room">+ Nuova sala</button><div class="room-cards">${state.rooms.map(r=>`<div class="panel room-card"><h3>${esc(r.name)}</h3><p>Online: <strong>${r.public_enabled?'Attivo':'Non attivo'}</strong></p><p>Interna: ${r.internal_enabled?'Sì':'No'}</p><button class="mini" data-edit-room="${r.id}">Modifica</button> <button class="mini danger" data-delete-room="${r.id}">Elimina</button></div>`).join('')}</div>`}
if(tab==='floor'){state.rooms=await api('admin/rooms');state.tables=await api('admin/tables');const room=state.rooms.find(x=>x.id===state.room)||state.rooms[0];state.room=room?.id;html=heading('Editor piantina','Aggiungi, trascina e salva la disposizione dei tavoli.')+`<div class="toolbar"><label>Sala <select id="room-select">${state.rooms.map(r=>`<option value="${r.id}" ${r.id===state.room?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><button class="btn btn-dark" id="new-table">+ Aggiungi tavolo</button></div><div class="floor-layout"><section class="panel"><div class="floor-board" id="floor-board">${state.tables.filter(t=>t.room_id===state.room).map(t=>`<div class="floor-table ${esc(t.shape)} ${t.enabled?'':'off'}" data-table="${t.id}" style="left:${t.x}px;top:${t.y}px;width:${t.w}px;height:${t.h}px;transform:rotate(${t.rotation}deg)"><span>${esc(t.code)}</span><small>${t.seats} posti</small></div>`).join('')}</div><p class="tiny">Trascina con mouse o dito per posizionare. Le coordinate si salvano al rilascio.</p></section><aside id="table-properties" class="panel"><h3>Seleziona un tavolo</h3><p>Seleziona un tavolo sulla piantina per modificarlo.</p></aside></div>`}
if(tab==='menu'){state.menu=await api('admin/menu');html=heading('Menù digitale','Gestisci piatti, pizze, vini, prezzi e allergeni.')+`<button class="btn btn-dark" id="new-menu">+ Aggiungi elemento</button><div id="edit-area"></div><section class="panel"><div class="table-scroll"><table><tr><th>Sezione</th><th>Categoria</th><th>Nome</th><th>Prezzo</th><th>Attivo</th><th>Azioni</th></tr>${state.menu.map(x=>`<tr><td>${esc(x.section)}</td><td>${esc(x.category)}</td><td>${esc(x.name)}</td><td>${esc(x.price)}</td><td>${x.available?'Sì':'No'}</td><td><button class="mini" data-edit-menu="${x.id}">Modifica</button> <button class="mini danger" data-delete-menu="${x.id}">Elimina</button></td></tr>`).join('')}</table></div></section>`}
if(tab==='gallery'){state.gallery=await api('admin/gallery');html=heading('Galleria','Aggiungi fotografie e ambienti.')+`<button class="btn btn-dark" id="new-gallery">+ Aggiungi foto</button><div id="edit-area"></div><div class="gallery-admin">${state.gallery.map(x=>`<article class="panel"><img src="${esc(x.image_url)}" alt=""/><h3>${esc(x.caption)}</h3><button class="mini" data-edit-gallery="${x.id}">Modifica</button> <button class="mini danger" data-delete-gallery="${x.id}">Elimina</button></article>`).join('')}</div>`}
if(tab==='site'||tab==='booking'){const cfg=await api('admin/settings');const d=cfg[tab];if(tab==='site')html=heading('Contenuti e contatti','Personalizza la storia e le informazioni del ristorante.')+sectionForm('Contenuti del sito',fields([['subtitle','Sottotitolo homepage'],['story','La nostra storia','textarea'],['heroImage','Fotografia copertina (URL)'],['storyImage','Fotografia Chi siamo (URL)'],['address','Indirizzo'],['phone','Telefono'],['instagram','Instagram'],['facebook','Facebook'],['tiktok','TikTok']],d));else html=heading('Orari e regole','Configura separatamente pranzo, cena e chiusure.')+sectionForm('Impostazioni prenotazione',fields([['lunchStart','Pranzo da','time'],['lunchLast','Pranzo ultimo arrivo','time'],['dinnerStart','Cena da','time'],['dinnerLast','Cena ultimo arrivo','time'],['maxOnline','Massimo persone online','number'],['maxDaysAhead','Giorni prenotabili in anticipo','number'],['minNoticeMinutes','Preavviso minimo (minuti)','number'],['closedDates','Date di chiusura (AAAA-MM-GG separate da virgola)']],{lunchStart:d.lunch.start,lunchLast:d.lunch.last,dinnerStart:d.dinner.start,dinnerLast:d.dinner.last,maxOnline:d.maxOnline,maxDaysAhead:d.maxDaysAhead,minNoticeMinutes:d.minNoticeMinutes,closedDates:d.closedDates.join(', ')}));state.settings=cfg}
root.innerHTML=adminShell(html,tab);bindAdmin();}catch(e){root.innerHTML=adminShell(heading('Errore',esc(e.message))+'<button class="btn btn-dark" id="retry">Riprova</button>',tab);bindAdmin();$('#retry')?.addEventListener('click',renderAdmin)}}
const tableFields=[['code','Codice tavolo'],['seats','Posti','number'],['shape','Forma (square, rectangle, circle)'],['group_code','Gruppo unione (facoltativo)'],['w','Larghezza','number'],['h','Altezza','number'],['rotation','Rotazione','number'],['enabled','Attivo','checkbox']];
const menuFields=[['section','Sezione: piatti, pizze, vini'],['category','Categoria'],['name','Nome'],['description','Descrizione','textarea'],['price','Prezzo (es. € 12,00)'],['allergens','Allergeni'],['image_url','URL foto'],['region','Regione vino'],['winery','Cantina'],['vintage','Annata'],['sort_order','Ordine','number'],['available','Disponibile','checkbox']];
const galleryFields=[['image_url','URL immagine'],['caption','Didascalia'],['category','Categoria'],['sort_order','Ordine','number']];
function editEntity(type,record={}){const form=type==='rooms'?[['name','Nome sala'],['sort_order','Ordine','number'],['public_enabled','Prenotabile online','checkbox'],['internal_enabled','Gestione interna attiva','checkbox']]:type==='tables'?tableFields:type==='menu'?menuFields:galleryFields;const zone=type==='tables'?$('#table-properties'):$('#edit-area');zone.innerHTML=sectionForm(record.id?'Modifica':'Nuovo elemento',fields(form,record),record.id?'Salva modifiche':'Crea');if(type==='gallery'||type==='menu'){zone.querySelector('#editor-form').insertAdjacentHTML('afterbegin','<div class="upload"><label>Carica fotografia da dispositivo<input type="file" id="upload-file" accept="image/png,image/jpeg,image/webp,image/avif" /></label><button type="button" class="mini" id="upload-action">Carica</button><span id="upload-status"></span></div>');$('#upload-action').onclick=async()=>{const file=$('#upload-file').files[0];if(!file)return msg('Scegli una foto','error');const f=new FormData();f.append('file',file);try{const r=await fetch('/api/admin/upload',{method:'POST',body:f});const o=await r.json();if(!r.ok)throw Error(o.error);zone.querySelector('[name="image_url"]').value=o.url;$('#upload-status').textContent='Foto caricata'}catch(e){msg(e.message,'error')}}}
zone.querySelector('#form-cancel').onclick=()=>{zone.innerHTML=''};zone.querySelector('#editor-form').onsubmit=async e=>{e.preventDefault();const b=parseForm(e.target);if(type==='tables'){b.room_id=state.room;b.x=record.x??55;b.y=record.y??55}try{await api('admin/'+type+(record.id?'/'+record.id:''),record.id?'PUT':'POST',b);msg('Salvato correttamente');renderAdmin()}catch(e){msg(e.message,'error')}}}
async function deleteEntity(type,id){if(!confirm('Vuoi davvero eliminare questo elemento?'))return;try{await api('admin/'+type+'/'+id,'DELETE');msg('Elemento eliminato');renderAdmin()}catch(e){msg(e.message,'error')}}
function bindAdmin(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.adminView=b.dataset.tab;renderAdmin()});$('#mobile-tab')?.addEventListener('change',e=>{state.adminView=e.target.value;renderAdmin()});$('#logout')?.addEventListener('click',async()=>{await api('admin/logout','POST',{});location.href='/admin'});$('#admin-date')?.addEventListener('change',e=>{state.date=e.target.value;renderAdmin()});$('#new-room')?.addEventListener('click',()=>editEntity('rooms',{internal_enabled:1}));$('#new-menu')?.addEventListener('click',()=>editEntity('menu',{section:'piatti',available:1}));$('#new-gallery')?.addEventListener('click',()=>editEntity('gallery',{}));document.querySelectorAll('[data-edit-room]').forEach(b=>b.onclick=()=>editEntity('rooms',state.rooms.find(x=>x.id==b.dataset.editRoom)));document.querySelectorAll('[data-edit-menu]').forEach(b=>b.onclick=()=>editEntity('menu',state.menu.find(x=>x.id==b.dataset.editMenu)));document.querySelectorAll('[data-edit-gallery]').forEach(b=>b.onclick=()=>editEntity('gallery',state.gallery.find(x=>x.id==b.dataset.editGallery)));document.querySelectorAll('[data-delete-room]').forEach(b=>b.onclick=()=>deleteEntity('rooms',b.dataset.deleteRoom));document.querySelectorAll('[data-delete-menu]').forEach(b=>b.onclick=()=>deleteEntity('menu',b.dataset.deleteMenu));document.querySelectorAll('[data-delete-gallery]').forEach(b=>b.onclick=()=>deleteEntity('gallery',b.dataset.deleteGallery));$('#room-select')?.addEventListener('change',e=>{state.room=Number(e.target.value);renderAdmin()});$('#new-table')?.addEventListener('click',()=>editEntity('tables',{shape:'square',seats:4,w:75,h:65,enabled:1,group_code:''}));document.querySelectorAll('.floor-table').forEach(el=>{const t=state.tables.find(x=>x.id===+el.dataset.table);el.onclick=()=>editEntity('tables',t);let start=null;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY,ox:t.x,oy:t.y};el.setPointerCapture(e.pointerId);el.classList.add('dragging')});el.addEventListener('pointermove',e=>{if(!start)return;const scale=1;t.x=Math.max(0,Math.min(780-t.w,Math.round(start.ox+(e.clientX-start.x)/scale)));t.y=Math.max(0,Math.min(490-t.h,Math.round(start.oy+(e.clientY-start.y)/scale)));el.style.left=t.x+'px';el.style.top=t.y+'px'});el.addEventListener('pointerup',async()=>{if(!start)return;start=null;el.classList.remove('dragging');try{await api('admin/tables/'+t.id,'PUT',t)}catch(e){msg(e.message,'error')}})});$('#editor-form')?.addEventListener('submit',async e=>{if(!['site','booking'].includes(state.adminView))return;e.preventDefault();const v=inputData(e.target);let obj=state.settings[state.adminView];if(state.adminView==='site')obj={...obj,...v};else obj={...obj,maxOnline:Number(v.maxOnline),maxDaysAhead:Number(v.maxDaysAhead),minNoticeMinutes:Number(v.minNoticeMinutes),closedDates:v.closedDates.split(',').map(x=>x.trim()).filter(Boolean),lunch:{...obj.lunch,start:v.lunchStart,last:v.lunchLast},dinner:{...obj.dinner,start:v.dinnerStart,last:v.dinnerLast}};try{await api('admin/settings/'+state.adminView,'PUT',obj);msg('Impostazioni salvate')}catch(x){msg(x.message,'error')}});
$('#new-book')?.addEventListener('click',()=>{const z=$('#edit-area');z.innerHTML=sectionForm('Prenotazione telefonica',`<label>Data<input name="date" type="date" value="${state.date}" required/></label><label>Servizio<select name="service"><option value="lunch">Pranzo</option><option value="dinner">Cena</option></select></label>${fields([['time','Ora di arrivo','time'],['party_size','Persone','number'],['name','Nome cliente'],['phone','Telefono'],['email','Email (facoltativa)','email'],['notes','Note']])}`,'Registra prenotazione');z.querySelector('[name=time]').value='12:30';z.querySelector('[name=party_size]').value=2;z.querySelector('#form-cancel').onclick=()=>z.innerHTML='';z.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('admin/reservations','POST',inputData(e.target));msg('Prenotazione registrata');renderAdmin()}catch(x){msg(x.message,'error')}}});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Annullare la prenotazione?'))return;try{await api('admin/reservations/'+b.dataset.cancel,'PATCH',{status:'cancelled'});renderAdmin()}catch(x){msg(x.message,'error')}});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const r=state.reservations.find(x=>x.id==b.dataset.move);const zone=$('#edit-area');zone.innerHTML=sectionForm('Sposta tavolo · Prenotazione '+r.id,`<label>Identificativi dei tavoli (separati da virgola)<input name="ids" value="${esc(r.table_ids||'')}" required/></label>`,'Salva assegnazione');zone.querySelector('#form-cancel').onclick=()=>zone.innerHTML='';zone.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('admin/reservations/'+r.id,'PATCH',{table_ids:e.target.elements.ids.value.split(',').map(Number)});renderAdmin()}catch(x){msg(x.message,'error')}}})}
async function start(){if(location.pathname==='/admin'){await loadAdmin();return}try{state.data=await api('public')}catch(e){state.data={site:{address:'Contrada Serrarossa, 88835 Roccabernarda KR',phone:'338 703 6868'},booking:{lunch:{start:'12:30',last:'14:30'},dinner:{start:'19:30',last:'23:00'}},gallery:[],menu:[]};msg('Configura il database per attivare prenotazioni e contenuti.','error')}renderPublic()}
start();
